1	/* ─── Footer CSS Module ───────────────────────────────────────────────────────
2	   Extracted verbatim from boldteq-v1-0.webflow.css
3	   ─────────────────────────────────────────────────────────────────────────── */
4	
5	/* ─── Outer footer section ───────────────────────────────────────────────────── */
6	
7	.footer {
8	  background-color: #082753;
9	  padding: 72px 5% 16px;
10	  position: relative;
11	}
12	
13	/* ─── Container ──────────────────────────────────────────────────────────────── */
14	
15	.container-large-6 {
16	  width: 100%;
17	  max-width: 1280px;
18	  margin-left: auto;
19	  margin-right: auto;
20	}
21	
22	/* ─── Outer column ───────────────────────────────────────────────────────────── */
23	
24	.column-x-large {
25	  grid-column-gap: 16px;
26	  grid-row-gap: 16px;
27	  flex-direction: column;
28	  display: flex;
29	}
30	
31	/* ─── Two-column grid (newsletter | links) ───────────────────────────────────── */
32	
33	.footer-grid {
34	  grid-column-gap: 3rem;
35	  grid-row-gap: 3rem;
36	  grid-template-rows: auto;
37	  grid-template-columns: 0.75fr 1.25fr;
38	  place-items: center stretch;
39	  display: grid;
40	}
41	
42	/* ─── Left: newsletter side ──────────────────────────────────────────────────── */
43	
44	.footer-main {
45	  grid-column-gap: 88px;
46	  grid-row-gap: 88px;
47	  flex-flow: row;
48	  max-width: none;
49	  display: flex;
50	}
51	
52	/* ─── Newsletter card ────────────────────────────────────────────────────────── */
53	
54	.footer-newsletter-card {
55	  grid-column-gap: 10px;
56	  grid-row-gap: 10px;
57	  opacity: 1;
58	  background-color: rgba(255, 255, 255, 0.3);
59	  background-image: radial-gradient(circle, #092854, rgba(9, 41, 85, 0.67));
60	  border: 0.5px solid rgba(5, 186, 254, 0.38);
61	  border-radius: 20px;
62	  flex-flow: column;
63	  padding: 30px;
64	  display: flex;
65	  box-shadow: 0 0 50px rgba(0, 0, 0, 0.2), inset 0 0 100px #092955;
66	  width: 100%;
67	}
68	
69	/* ─── Newsletter title block ─────────────────────────────────────────────────── */
70	
71	.footer-newsletter-title {
72	  grid-column-gap: 0px;
73	  grid-row-gap: 0px;
74	  flex-flow: column;
75	  padding: 0;
76	  display: flex;
77	}
78	
79	/* ─── "Join 500+ Subscribers" pill ──────────────────────────────────────────── */
80	
81	.news-subhead-out {
82	  grid-column-gap: 10px;
83	  grid-row-gap: 10px;
84	  justify-content: flex-start;
85	  align-items: center;
86	  margin-bottom: 15px;
87	  display: flex;
88	}
89	
90	.newsubott {
91	  grid-column-gap: 5px;
92	  grid-row-gap: 5px;
93	  background-color: rgba(33, 207, 255, 0.07);
94	  border: 1.5px solid #05bafe;
95	  border-radius: 20px;
96	  margin-bottom: 0;
97	  padding: 0 13px;
98	  line-height: 14px;
99	  display: flex;
100	  align-items: center;
101	}
102	
103	/* ─── Newsletter heading ─────────────────────────────────────────────────────── */
104	
105	.heading-2-news {
106	  margin: 0 0 0 0;
107	  color: #fff;
108	  font-family: Roobert PRO, Arial, sans-serif;
109	  font-size: 28px;
110	  font-weight: 700;
111	  line-height: 1.25;
112	  text-align: left;
113	}
114	
115	.gradient-span {
116	  color: #05bafe;
117	}
118	
119	/* ─── Newsletter sub-text ────────────────────────────────────────────────────── */
120	
121	.paragraph-small-4-gray {
122	  color: #c0dbff;
123	  margin-bottom: 0;
124	  font-family: Roobert PRO, Arial, sans-serif;
125	  font-size: 16px;
126	  font-weight: 400;
127	  line-height: 24px;
128	}
129	
130	/* ─── Newsletter form block ──────────────────────────────────────────────────── */
131	
132	.footer-newsletter-form-block {
133	  background-color: transparent;
134	  border-radius: 0;
135	  margin-top: 13px;
136	  margin-bottom: 0;
137	  padding: 0;
138	}
139	
140	/* ─── Form inner column ──────────────────────────────────────────────────────── */
141	
142	.column-large {
143	  grid-column-gap: 24px;
144	  grid-row-gap: 24px;
145	  flex-direction: column;
146	  display: flex;
147	}
148	
149	.column-large.row-gap-0 {
150	  grid-row-gap: 0px;
151	}
152	
153	.column-tiny-2 {
154	  grid-column-gap: 4px;
155	  grid-row-gap: 4px;
156	  flex-direction: column;
157	  justify-content: center;
158	  display: flex;
159	  position: relative;
160	}
161	
162	/* ─── Email input ────────────────────────────────────────────────────────────── */
163	
164	.text-field-small {
165	  color: #23272f;
166	  border: 1px solid #edeff3;
167	  border-radius: 8px;
168	  min-height: 55px;
169	  margin-bottom: 0;
170	  padding: 8px 12px;
171	  font-family: Roobert PRO, Arial, sans-serif;
172	  font-size: 14px;
173	  line-height: 20px;
174	  width: 100%;
175	  outline: none;
176	  box-sizing: border-box;
177	  padding-right: 130px;
178	}
179	
180	.text-field-small:focus {
181	  border-color: #b1bbc8;
182	}
183	
184	.text-field-small::placeholder {
185	  color: #525f75;
186	}
187	
188	/* ─── Submit button ──────────────────────────────────────────────────────────── */
189	
190	.button-secondary-small {
191	  color: #fff;
192	  background-color: #23272f;
193	  background-image: linear-gradient(90deg, #21cfff, #019ae6);
194	  border: 2px solid #23272f;
195	  border-radius: 10px;
196	  justify-content: center;
197	  align-items: center;
198	  padding: 12px 20px;
199	  font-family: Roobert PRO, Arial, sans-serif;
200	  font-size: 16px;
201	  font-weight: 700;
202	  text-decoration: none;
203	  display: flex;
204	  position: absolute;
205	  inset: auto 1.5% auto auto;
206	  top: 50%;
207	  transform: translateY(-50%);
208	  overflow: hidden;
209	  cursor: pointer;
210	  transition: opacity 0.2s;
211	}
212	
213	.button-secondary-small:hover {
214	  opacity: 0.9;
215	  border-width: 0;
216	}
217	
218	/* ─── Success / error message states ─────────────────────────────────────────── */
219	
220	.success-message {
221	  color: #082753;
222	  background-color: #def4ff;
223	  border-radius: 12px;
224	  font-family: Roobert PRO, Arial, sans-serif;
225	  font-weight: 500;
226	  padding: 12px 16px;
227	  font-size: 14px;
228	}
229	
230	.error-message {
231	  color: #460906;
232	  background-color: #fff2eb;
233	  border-radius: 8px;
234	  padding: 12px 16px;
235	  margin-top: 8px;
236	  font-size: 14px;
237	}
238	
239	/* ─── Privacy line under form ────────────────────────────────────────────────── */
240	
241	.newsletter-btm-line {
242	  grid-column-gap: 5px;
243	  grid-row-gap: 5px;
244	  justify-content: center;
245	  align-items: center;
246	  margin-top: 5px;
247	  display: flex;
248	}
249	
250	.shield-icon {
251	  width: 14px;
252	  height: 14px;
253	  flex-shrink: 0;
254	}
255	
256	.news-btm-para {
257	  color: rgba(181, 211, 245, 0.51);
258	  margin-bottom: 0;
259	  font-family: Roobert PRO, Arial, sans-serif;
260	  font-weight: 400;
261	  font-size: 13px;
262	}
263	
264	/* ─── Right side (logo + social + links) ─────────────────────────────────────── */
265	
266	.footer-right {
267	  grid-column-gap: 2.8rem;
268	  grid-row-gap: 2.8rem;
269	  flex-flow: column;
270	  display: flex;
271	}
272	
273	/* ─── Logo + social row ──────────────────────────────────────────────────────── */
274	
275	.footer-heading {
276	  grid-column-gap: 32px;
277	  grid-row-gap: 32px;
278	  flex-flow: row;
279	  justify-content: space-between;
280	  align-items: flex-end;
281	  display: flex;
282	}
283	
284	.footer-column {
285	  grid-column-gap: 12px;
286	  grid-row-gap: 12px;
287	  flex-direction: column;
288	  max-width: 308px;
289	  display: flex;
290	}
291	
292	.footer-logo {
293	  text-decoration: none;
294	  display: block;
295	}
296	
297	/* ─── Social icon row ────────────────────────────────────────────────────────── */
298	
299	.row-regular {
300	  grid-column-gap: 16px;
301	  grid-row-gap: 16px;
302	  display: flex;
303	  align-items: center;
304	}
305	
306	.footer-social-link {
307	  color: #000;
308	  background-color: rgba(255, 255, 255, 0.05);
309	  border-radius: 10px;
310	  flex: none;
311	  justify-content: center;
312	  align-items: center;
313	  width: 38px;
314	  height: 38px;
315	  padding: 0;
316	  transition: box-shadow 0.3s;
317	  display: flex;
318	  box-shadow: 0 1px 2px rgba(35, 39, 46, 0.08);
319	  text-decoration: none;
320	}
321	
322	.footer-social-link:hover {
323	  box-shadow: 0 2px 4px rgba(35, 39, 46, 0.16);
324	}
325	
326	/* ─── Links grid (4 columns) ─────────────────────────────────────────────────── */
327	
328	.footer-links-grid {
329	  grid-column-gap: 24px;
330	  grid-row-gap: 56px;
331	  border: 1px rgba(255, 255, 255, 0.05);
332	  border-top-style: solid;
333	  grid-template-rows: auto;
334	  grid-template-columns: 0.75fr 1.25fr 1fr 1fr;
335	  grid-auto-columns: 1fr;
336	  padding-top: 2.8rem;
337	  display: grid;
338	}
339	
340	/* ─── Link column ────────────────────────────────────────────────────────────── */
341	
342	.column-x-large-inner {
343	  grid-column-gap: 16px;
344	  grid-row-gap: 16px;
345	  flex-direction: column;
346	  display: flex;
347	}
348	
349	.footer-title {
350	  color: #fff;
351	  text-transform: capitalize;
352	  font-family: Roobert PRO, Arial, sans-serif;
353	  font-size: 18px;
354	  font-weight: 700;
355	  line-height: 22px;
356	}
357	
358	.column-regular-2 {
359	  grid-column-gap: 16px;
360	  grid-row-gap: 16px;
361	  flex-direction: column;
362	  display: flex;
363	}
364	
365	.footer-link {
366	  color: rgba(255, 255, 255, 0.8);
367	  font-family: Roobert PRO, Arial, sans-serif;
368	  font-size: 16px;
369	  line-height: 24px;
370	  text-decoration: none;
371	  transition: color 0.3s;
372	}
373	
374	.footer-link:hover {
375	  color: #fff;
376	}
377	
378	.footer-link.disabled {
379	  pointer-events: none;
380	  cursor: default;
381	}
382	
383	/* ─── Coming soon row inside links ──────────────────────────────────────────── */
384	
385	.coming-soon-out {
386	  grid-column-gap: 10px;
387	  grid-row-gap: 10px;
388	  padding-top: 0;
389	  display: flex;
390	  position: static;
391	  align-items: center;
392	}
393	
394	.coming-soon-badge {
395	  color: #1890ff;
396	  text-align: center;
397	  background-color: #e6f7ff;
398	  border-radius: 4px;
399	  align-self: center;
400	  margin-bottom: 0;
401	  padding: 2px 4px;
402	  font-family: Roobert PRO, Arial, sans-serif;
403	  font-size: 10px;
404	  font-weight: 500;
405	  line-height: 12px;
406	  white-space: nowrap;
407	}
408	
409	/* ─── Legal / copyright row ──────────────────────────────────────────────────── */
410	
411	.footer-legal-wrapper {
412	  grid-column-gap: 9px;
413	  grid-row-gap: 9px;
414	  justify-content: center;
415	  align-items: center;
416	  margin-top: 20px;
417	  display: flex;
418	}
419	
420	.copyright-outer {
421	  grid-column-gap: 10px;
422	  grid-row-gap: 10px;
423	  text-align: center;
424	  background-color: #113569;
425	  border-radius: 10px;
426	  flex: 0 auto;
427	  justify-content: center;
428	  align-items: center;
429	  padding: 4px 15px;
430	  display: flex;
431	}
432	
433	.copyright-text {
434	  color: #fff;
435	  margin-bottom: 0;
436	  font-family: Roobert PRO, Arial, sans-serif;
437	  font-size: 16px;
438	  line-height: 24px;
439	}
440	
441	.indian-flag {
442	  width: 18px;
443	  height: 18px;
444	  margin-top: 3px;
445	  padding-top: 0;
446	}
447	
448	/* ─── Icon helper ────────────────────────────────────────────────────────────── */
449	
450	.icon-regular {
451	  width: 20px;
452	  height: 20px;
453	  display: flex;
454	  align-items: center;
455	  justify-content: center;
456	}
457	
458	/* ─── Responsive: min-width 1440px ──────────────────────────────────────────── */
459	
460	@media screen and (min-width: 1440px) {
461	  .footer-newsletter-card {
462	    padding: 30px;
463	  }
464	
465	  .container-large-6 {
466	    max-width: 1320px;
467	  }
468	
469	  .footer-links-grid {
470	    grid-template-columns: 0.75fr 1.5fr 1fr 0.85fr;
471	  }
472	
473	  .footer {
474	    padding-bottom: 16px;
475	  }
476	}
477	
478	/* ─── Responsive: min-width 1280px ──────────────────────────────────────────── */
479	
480	@media screen and (min-width: 1280px) {
481	  .container-large-6 {
482	    max-width: 1320px;
483	  }
484	
485	  .footer-links-grid {
486	    grid-template-columns: 0.75fr 1.25fr 1fr 0.75fr;
487	  }
488	
489	  .footer {
490	    padding-bottom: 16px;
491	  }
492	}
493	
494	/* ─── Responsive: max-width 991px ───────────────────────────────────────────── */
495	
496	@media screen and (max-width: 991px) {
497	  .footer-newsletter-card,
498	  .footer-grid {
499	    grid-template-columns: 1fr;
500	  }
501	
502	  .footer-grid {
503	    grid-template-columns: 1fr;
504	  }
505	
506	  .footer-legal-wrapper {
507	    flex-flow: column;
508	    justify-content: flex-start;
509	    align-items: center;
510	  }
511	
512	  .footer-main {
513	    max-width: none;
514	  }
515	
516	  .footer-links-grid {
517	    grid-template-columns: 1fr 1fr 1fr 1fr;
518	    padding-top: 2rem;
519	  }
520	
521	  .footer {
522	    padding-bottom: 16px;
523	  }
524	}
525	
526	/* ─── Responsive: max-width 767px ───────────────────────────────────────────── */
527	
528	@media screen and (max-width: 767px) {
529	  .footer-heading {
530	    flex-flow: column;
531	    justify-content: flex-start;
532	    align-items: flex-start;
533	  }
534	
535	  .footer-legal-wrapper {
536	    margin-top: 40px;
537	  }
538	
539	  .footer-links-grid {
540	    grid-template-columns: 1fr 1fr;
541	  }
542	
543	  .footer {
544	    padding-bottom: 16px;
545	  }
546	}
547	
548	/* ─── Responsive: max-width 479px ───────────────────────────────────────────── */
549	
550	@media screen and (max-width: 479px) {
551	  .footer-link {
552	    font-size: 14px;
553	    line-height: 20px;
554	  }
555	
556	  .column-x-large {
557	    grid-column-gap: 16px;
558	    grid-row-gap: 16px;
559	  }
560	
561	  .footer-newsletter-card {
562	    grid-column-gap: 5px;
563	    grid-row-gap: 5px;
564	    padding: 20px 16px;
565	  }
566	
567	  .footer-newsletter-title {
568	    grid-column-gap: 10px;
569	    grid-row-gap: 10px;
570	  }
571	
572	  .button-secondary-small {
573	    margin-top: 10px;
574	    position: relative;
575	    right: auto;
576	    top: auto;
577	    transform: none;
578	    inset: auto;
579	    width: 100%;
580	  }
581	
582	  .text-field-small {
583	    padding-right: 12px;
584	  }
585	
586	  .footer-newsletter-form-block {
587	    margin-top: 0;
588	    padding: 20px 0 10px;
589	  }
590	
591	  .footer-legal-wrapper {
592	    margin-top: 20px;
593	  }
594	
595	  .footer-links-grid {
596	    grid-row-gap: 30px;
597	    border-top-style: none;
598	    grid-template-columns: 0.75fr 1fr;
599	    padding-top: 0;
600	  }
601	
602	  .footer {
603	    padding-bottom: 16px;
604	  }
605	
606	  .news-subhead-out {
607	    margin-bottom: 0;
608	  }
609	
610	  .newsletter-btm-line {
611	    grid-column-gap: 7px;
612	    grid-row-gap: 7px;
613	    justify-content: center;
614	    align-items: flex-start;
615	  }
616	}
