1	/* ============================================================
2	   FEATURED LOGOS — featured-logos.module.css
3	   Extracted verbatim from boldteq-v1-0.webflow.css
4	   ============================================================ */
5	
6	.section-regular {
7	  background-color: #fff;
8	  padding: 0 5%;
9	  position: relative;
10	  overflow: visible;
11	}
12	
13	.no-padding-mob {
14	  /* base — see mobile media query for override */
15	}
16	
17	.logo-mob {
18	  /* base — see mobile media query for override */
19	}
20	
21	.logo-3-title {
22	  text-align: center;
23	  flex-flow: column;
24	  justify-content: flex-start;
25	  align-items: center;
26	  max-width: 628px;
27	  margin-bottom: 20px;
28	  margin-left: auto;
29	  margin-right: auto;
30	  display: flex;
31	}
32	
33	.paragraph-x-large {
34	  margin-bottom: 0;
35	  font-size: 20px;
36	  line-height: 1.5;
37	}
