64	  opacity: 0.4;
65	  justify-content: center;
66	  align-items: center;
67	  min-width: auto;
68	  padding: 0;
69	  display: flex;
70	}
71	
72	.logo-3-block:hover {
73	  opacity: 1;
74	}
75	
76	.logo-3-icon {
77	  /* dimension set per image */
78	}
79	
80	/* ============================================================
81	   max-width: 767px
82	   ============================================================ */
