84	  .logo-3-block {
85	    min-width: 150px;
86	  }
87	
88	  .logo-3-content {
89	    grid-column-gap: 12px;
90	    grid-row-gap: 12px;
91	  }
92	
93	  .paragraph-x-large {
94	    font-size: 18px;
95	  }
96	}
97	
98	/* ============================================================
99	   max-width: 479px  (mobile)
100	   ============================================================ */
101	@media screen and (max-width: 479px) {
102	  .section-regular.no-padding-mob {
103	    padding-left: 0%;
104	    padding-right: 0%;
105	  }
106	
107	  .section-regular.no-padding-mob.logo-mob {
108	    padding-top: 40px;
109	  }
110	
111	  .logo-3-block {
112	    justify-content: center;
113	    align-items: center;
114	    width: auto;
115	    min-width: auto;
116	  }
117	
118	  .logo-3-title {
119	    margin-bottom: 10px;
120	  }
121	
122	  .logo-3-content {
123	    grid-column-gap: 30px;
124	    grid-row-gap: 30px;
125	    flex-flow: row;
126	    display: flex;
127	  }
128	}
