1	/* ============================================================
2	   HOW WORKS HERO — how-works-hero.module.css
3	   ============================================================ */
4	
5	.section {
6	  background-color: #fff;
7	  background-image: url('/images/webflow/hero-background-1.png'), linear-gradient(#019ae614, #019ae600);
8	  background-position: 50% 100%, 0 0;
9	  background-repeat: no-repeat, repeat;
10	  background-size: cover, auto;
11	  padding-top: 4rem;
12	  padding-bottom: 4rem;
13	  position: relative;
14	}
15	
16	.container {
17	  max-width: 80rem;
18	  margin-left: auto;
19	  margin-right: auto;
20	  padding-left: 2rem;
21	  padding-right: 2rem;
22	}
23	
24	.inner {
25	  text-align: center;
26	  max-width: 70rem;
27	  margin-left: auto;
28	  margin-right: auto;
29	}
